template:
PREFIX s: <https://schema.org/>
PREFIX seeds: <https://seeds.local/ontology/>
SELECT DISTINCT ?item ?id ?status ?title ?description ?owner ?modified ?label
FROM <{board}>
WHERE {
 ?item s:identifier "{identifier}" ; a s:Action ; s:identifier ?id ; seeds:status ?status ;
       s:name ?title ; s:dateModified ?modified ; s:keywords ?label .
 FILTER(?label IN ("stiwi-directive", "design", "plan"))
 FILTER(?status IN ("open", "in_progress", "blocked", "deferred"))
 OPTIONAL { ?item s:description ?description }
 OPTIONAL { ?item s:agent ?owner }

}
ORDER BY ?item ?label
LIMIT 101
